PREFIX cdm: <http://publications.europa.eu/ontology/cdm#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?baseCelex ?work ?date ?inForce ?versionCelex ?versionDate WHERE {
 VALUES ?baseCelex { "32017L0828"^^xsd:string "32017R1943"^^xsd:string "32017R2055"^^xsd:string "32019R2088"^^xsd:string "32021R0451"^^xsd:string "32024L0927"^^xsd:string "31978L0660"^^xsd:string "31986L0635"^^xsd:string "31991L0674"^^xsd:string "32004L0109"^^xsd:string "32005L0060"^^xsd:string "32006L0046"^^xsd:string "32006L0070"^^xsd:string "32006R1893"^^xsd:string "32007L0064"^^xsd:string "32008R0295"^^xsd:string "32009R0250"^^xsd:string "32010L0043"^^xsd:string "32010R0584"^^xsd:string "32013L0050"^^xsd:string "32013R0549"^^xsd:string "32014L0017"^^xsd:string "32014L0049"^^xsd:string "32014R0527"^^xsd:string }
 ?work cdm:resource_legal_id_celex ?baseCelex .
 OPTIONAL { ?work cdm:work_date_document ?date . }
 OPTIONAL { ?work cdm:resource_legal_in-force ?inForce . }
 OPTIONAL { ?version cdm:act_consolidated_based_on_resource_legal ?work ; cdm:act_consolidated_date ?versionDate ; cdm:resource_legal_id_celex ?versionCelex . }
} ORDER BY ?baseCelex DESC(?versionDate) LIMIT 10000
